"/bank/statement/import" : {
  "post" : {
    "tags" : [ "bank/statement" ],
    "summary" : "Upload bank statement file.",
    "operationId" : "BankStatementImport_importBankStatement",
    "parameters" : [ {
      "name" : "bankId",
      "in" : "query",
      "description" : "Bank ID",
      "required" : true,
      "schema" : {
        "type" : "integer",
        "format" : "int64"
      }
    }, {
      "name" : "accountId",
      "in" : "query",
      "description" : "Account ID",
      "required" : true,
      "schema" : {
        "type" : "integer",
        "format" : "int64"
      }
    }, {
      "name" : "fromDate",
      "in" : "query",
      "description" : "Format is yyyy-MM-dd (from and incl.).",
      "required" : true,
      "schema" : {
        "type" : "string"
      }
    }, {
      "name" : "toDate",
      "in" : "query",
      "description" : "Format is yyyy-MM-dd (to and excl.).",
      "required" : true,
      "schema" : {
        "type" : "string"
      }
    }, {
      "name" : "externalId",
      "in" : "query",
      "description" : "External ID",
      "schema" : {
        "type" : "string"
      }
    }, {
      "name" : "fileFormat",
      "in" : "query",
      "description" : "File format",
      "required" : true,
      "schema" : {
        "type" : "string",
        "enum" : [ "DNB_CSV", "EIKA_TELEPAY", "SPAREBANK1_TELEPAY", "VISMA_ACCOUNT_STATEMENT", "HANDELSBANKEN_TELEPAY", "SPAREBANKEN_VEST_TELEPAY", "NORDEA_CSV", "TRANSFERWISE", "SPAREBANKEN_SOR_TELEPAY", "SPAREBANKEN_OST_TELEPAY", "DANSKE_BANK_CSV", "CULTURA_BANK_TELEPAY", "SBANKEN_PRIVAT_CSV", "HAUGESUND_SPAREBANK_CSV", "VISMA_ACCOUNT_STATEMENT_PSD2", "SBANKEN_BEDRIFT_CSV", "LANDKREDITT_TELEPAY", "ZTL", "VISMA_ACCOUNT_STATEMENT_PLATFORM_AGNOSTIC", "VISMA_ACCOUNT_STATEMENT_PDS2_PLATFORM_AGNOSTIC" ]
      }
    } ],
    "requestBody" : {
      "content" : {
        "multipart/form-data" : {
          "schema" : {
            "required" : [ "file" ],
            "type" : "object",
            "properties" : {
              "file" : {
                "type" : "string",
                "description" : "The bank statement file",
                "format" : "binary"
              }
            }
          }
        }
      }
    },
    "responses" : {
      "201" : {
        "description" : "successfully created",
        "content" : {
          "application/json" : {
            "schema" : {
              "$ref" : "#/components/schemas/ResponseWrapperBankStatement"
            }
          }
        }
      }
    },
    "security" : [ {
      "tokenAuthScheme" : [ ]
    } ]
  }
},

